// Cloudflare Worker entry: the Next.js site (built by OpenNext) plus the daily email job.
// .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

const worker = {
  fetch: handler.fetch,

  /** Cron trigger (see wrangler.jsonc): calls the site's own /api/cron, like Vercel Cron did. */
  async scheduled(_event, env, ctx) {
    const site = (env.SITE_URL || "https://hilleliis.ee").replace(/\/$/, "");
    const request = new Request(`${site}/api/cron`, { headers: { Authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (res) => console.log("daily job:", res.status, await res.text())),
    );
  },
};

export default worker;
